-- ======================================================
-- V0065（回滚）：删除批次 B 三模块的 15 个权限节点与超管授权
--
-- 顺序：先删授权（`sys_role_menu` 有指向 `sys_menu` 的外键），再删菜单。
-- 只删本迁移自己插入的固定 UUID，不触碰其它种子（V0045/V0046/V0047/V0052）。
-- ======================================================

DELETE FROM sys_role_menu
WHERE menu_id IN (
    '20000000-0000-0000-0000-000000000600'::uuid,
    '20000000-0000-0000-0000-000000000601'::uuid,
    '20000000-0000-0000-0000-000000000602'::uuid,
    '20000000-0000-0000-0000-000000000603'::uuid,
    '20000000-0000-0000-0000-000000000610'::uuid,
    '20000000-0000-0000-0000-000000000611'::uuid,
    '20000000-0000-0000-0000-000000000612'::uuid,
    '20000000-0000-0000-0000-000000000613'::uuid,
    '20000000-0000-0000-0000-000000000614'::uuid,
    '20000000-0000-0000-0000-000000000615'::uuid,
    '20000000-0000-0000-0000-000000000620'::uuid,
    '20000000-0000-0000-0000-000000000621'::uuid,
    '20000000-0000-0000-0000-000000000622'::uuid,
    '20000000-0000-0000-0000-000000000623'::uuid,
    '20000000-0000-0000-0000-000000000624'::uuid
);

DELETE FROM sys_menu
WHERE id IN (
    '20000000-0000-0000-0000-000000000600'::uuid,
    '20000000-0000-0000-0000-000000000601'::uuid,
    '20000000-0000-0000-0000-000000000602'::uuid,
    '20000000-0000-0000-0000-000000000603'::uuid,
    '20000000-0000-0000-0000-000000000610'::uuid,
    '20000000-0000-0000-0000-000000000611'::uuid,
    '20000000-0000-0000-0000-000000000612'::uuid,
    '20000000-0000-0000-0000-000000000613'::uuid,
    '20000000-0000-0000-0000-000000000614'::uuid,
    '20000000-0000-0000-0000-000000000615'::uuid,
    '20000000-0000-0000-0000-000000000620'::uuid,
    '20000000-0000-0000-0000-000000000621'::uuid,
    '20000000-0000-0000-0000-000000000622'::uuid,
    '20000000-0000-0000-0000-000000000623'::uuid,
    '20000000-0000-0000-0000-000000000624'::uuid
);
